"""UI-neutral design state for the Simulink Field Study application."""

from __future__ import annotations

from dataclasses import dataclass
import sys


@dataclass(slots=True)
class FieldStudyDesignSpec:
    """Reference one validated request generated by MATLAB initialization."""

    request_file: str = ""

    def missing_required_inputs(self) -> list[str]:
        return [] if self.request_file.strip() else ["Field study request JSON"]

    def build_command(self, *, python: str | None = None) -> list[str]:
        if self.missing_required_inputs():
            raise ValueError("Field Study requires request_file.")
        return [
            python or sys.executable,
            "-m",
            "radia_mcp.radia_ngsolve.field_study_cli",
            "--request",
            self.request_file,
            "--msh-output",
            "field_study.msh",
            "--output",
            "field_study.json",
        ]
